package com.example.evcharging.finance.reconciliation;
import com.example.evcharging.framework.api.ApiResponse;import com.example.evcharging.framework.context.RequestContext;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;import java.util.*;
@RestController @RequestMapping("/admin-api/v1/finance/channel-bills") public class ChannelBillAdminController {private final ChannelBillApplicationService service;private final ChannelBillRawImportService rawImport;private final JdbcTemplate jdbc;public ChannelBillAdminController(ChannelBillApplicationService s,ChannelBillRawImportService raw,JdbcTemplate j){service=s;rawImport=raw;jdbc=j;}@PostMapping("/import") public ApiResponse<Map<String,String>> importBill(@RequestBody ChannelBillApplicationService.ImportRequest r){return ApiResponse.ok(Map.of("batchNo",service.importBill(r)));}@GetMapping public ApiResponse<List<BatchView>> list(@RequestParam(defaultValue="50")int limit){long t=RequestContext.requireTenantId();int size=Math.max(1,Math.min(limit,200));return ApiResponse.ok(jdbc.query("SELECT batch_no,channel,merchant_id,business_date,record_count,total_amount_fen,total_refund_fen,status,create_time FROM finance_channel_bill_batch WHERE tenant_id=? ORDER BY id DESC LIMIT ?",(rs,n)->new BatchView(rs.getString(1),rs.getString(2),rs.getString(3),String.valueOf(rs.getObject(4)),rs.getInt(5),rs.getLong(6),rs.getLong(7),rs.getString(8),String.valueOf(rs.getObject(9))),t,size));}@PostMapping(value="/import-raw",consumes="multipart/form-data") public ApiResponse<Map<String,String>> importRaw(@RequestPart("file") MultipartFile file){return ApiResponse.ok(Map.of("batchNo",rawImport.importJson(file)));}public record BatchView(String batchNo,String channel,String merchantId,String businessDate,int recordCount,long totalAmountFen,long totalRefundFen,String status,String createTime){}
}
